"use client";

import { useRef } from "react";
import { motion, useMotionValue, useMotionTemplate, useReducedMotion, useSpring, useTransform } from "framer-motion";

export function SpotlightCard({ children }: { children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const mouseX = useMotionValue(190);
  const mouseY = useMotionValue(90);

  const rotateX = useSpring(
    useTransform(mouseY, [0, 180], shouldReduceMotion ? [0, 0] : [6, -6]),
    { stiffness: 300, damping: 30 }
  );
  const rotateY = useSpring(
    useTransform(mouseX, [0, 380], shouldReduceMotion ? [0, 0] : [-6, 6]),
    { stiffness: 300, damping: 30 }
  );

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    mouseX.set(e.clientX - rect.left);
    mouseY.set(e.clientY - rect.top);
  };

  const background = useMotionTemplate`radial-gradient(200px circle at ${mouseX}px ${mouseY}px, rgba(217,119,6,0.15), transparent 80%)`;
  const borderGlow = useMotionTemplate`radial-gradient(160px circle at ${mouseX}px ${mouseY}px, rgba(245,158,11,0.8), transparent 70%)`;

  return (
    <div style={{ perspective: 800 }}>
      <motion.div
        ref={ref}
        onMouseMove={handleMouseMove}
        style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
        className="group relative rounded-2xl bg-slate-200 p-px transition-shadow duration-300 hover:shadow-xl dark:bg-slate-700"
      >
        <motion.div
          aria-hidden
          className="pointer-events-none absolute -inset-px rounded-2xl opacity-0 transition-opacity duration-300 group-hover:opacity-100"
          style={{ background: borderGlow }}
        />
        <div className="relative overflow-hidden rounded-[15px] bg-white p-6 dark:bg-neutral-950">
          <motion.div
            aria-hidden
            className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100"
            style={{ background }}
          />
          <div className="relative">{children}</div>
        </div>
      </motion.div>
    </div>
  );
}
